-- Skip indexes and the primary key must select the rows the comparison selects. A `FixedString` compares zero-padded:
-- an index looks up the stored value equal to the constant, and declines a constant that equals several stored values.
-- Each line: index, predicate, rows with the index, whether that equals the rows without it.

SET allow_experimental_full_text_index = 1;

DROP TABLE IF EXISTS tab_s_primary_key;
CREATE TABLE tab_s_primary_key (v String) ENGINE = MergeTree ORDER BY v SETTINGS index_granularity = 1;
INSERT INTO tab_s_primary_key SELECT arrayJoin(['ab', 'ab\0', 'ab\0\0', 'zz']);
DROP TABLE IF EXISTS tab_s_minmax;
CREATE TABLE tab_s_minmax (k UInt32, v String, INDEX idx v TYPE minmax GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_minmax SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));
DROP TABLE IF EXISTS tab_s_set;
CREATE TABLE tab_s_set (k UInt32, v String, INDEX idx v TYPE set(0) GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_set SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));
DROP TABLE IF EXISTS tab_s_bloom_filter;
CREATE TABLE tab_s_bloom_filter (k UInt32, v String, INDEX idx v TYPE bloom_filter GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_bloom_filter SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));
