CREATE TABLE tab_s_tokenbf_v1 (k UInt32, v String, INDEX idx v TYPE tokenbf_v1(512, 2, 0) GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_tokenbf_v1 SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));
DROP TABLE IF EXISTS tab_s_ngrambf_v1;
CREATE TABLE tab_s_ngrambf_v1 (k UInt32, v String, INDEX idx v TYPE ngrambf_v1(2, 512, 2, 0) GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_ngrambf_v1 SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));
DROP TABLE IF EXISTS tab_s_text_array;
CREATE TABLE tab_s_text_array (k UInt32, v String, INDEX idx v TYPE text(tokenizer = array) GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_text_array SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));
DROP TABLE IF EXISTS tab_s_text_splitByNonAlpha;
CREATE TABLE tab_s_text_splitByNonAlpha (k UInt32, v String, INDEX idx v TYPE text(tokenizer = splitByNonAlpha) GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_s_text_splitByNonAlpha SELECT number, ['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1] FROM numbers(length(['ab', 'ab\0', 'ab\0\0', 'zz']));

