SELECT '-- the index is still used for the stored value equal to the constant';
SELECT 'tab_f_primary_key', 'v = toFixedString(\'ab\', 6)', count() FROM tab_f_primary_key WHERE v = toFixedString('ab', 6) SETTINGS force_primary_key = 1;
SELECT 'tab_f_primary_key', 'v = \'ab\\0\'', count() FROM tab_f_primary_key WHERE v = 'ab\0' SETTINGS force_primary_key = 1;
SELECT 'tab_f_primary_key', 'v IN (SELECT toFixedString(\'ab\', 6))', count() FROM tab_f_primary_key WHERE v IN (SELECT toFixedString('ab', 6)) SETTINGS force_primary_key = 1;
SELECT 'tab_s_primary_key', 'v = \'ab\'', count() FROM tab_s_primary_key WHERE v = 'ab' SETTINGS force_primary_key = 1;
SELECT 'tab_f_bloom_filter', 'v = toFixedString(\'ab\', 6)', count() FROM tab_f_bloom_filter WHERE v = toFixedString('ab', 6) SETTINGS force_data_skipping_indices = 'idx';
SELECT 'tab_f_bloom_filter', 'v IN (SELECT toFixedString(\'ab\', 6))', count() FROM tab_f_bloom_filter WHERE v IN (SELECT toFixedString('ab', 6)) SETTINGS force_data_skipping_indices = 'idx';
SELECT 'tab_f_text_array', 'v = \'ab\\0\'', count() FROM tab_f_text_array WHERE v = 'ab\0' SETTINGS force_data_skipping_indices = 'idx';
SELECT 'tab_s_text_splitByNonAlpha', 'v = toFixedString(\'ab\', 4)', count() FROM tab_s_text_splitByNonAlpha WHERE v = toFixedString('ab', 4) SETTINGS force_data_skipping_indices = 'idx';
SELECT 'tab_s_tokenbf_v1', 'v = toFixedString(\'ab\', 4)', count() FROM tab_s_tokenbf_v1 WHERE v = toFixedString('ab', 4) SETTINGS force_data_skipping_indices = 'idx';

SELECT '-- a FixedString constant equals several String values, so an exact lookup declines';
SELECT count() FROM tab_s_primary_key WHERE v = toFixedString('ab', 4) SETTINGS force_primary_key = 1; -- { serverError INDEX_NOT_USED }
SELECT count() FROM tab_s_bloom_filter WHERE v = toFixedString('ab', 2) SETTINGS force_data_skipping_indices = 'idx'; -- { serverError INDEX_NOT_USED }
SELECT count() FROM tab_s_bloom_filter WHERE v IN (SELECT toFixedString('ab', 4)) SETTINGS force_data_skipping_indices = 'idx'; -- { serverError INDEX_NOT_USED }
SELECT count() FROM tab_s_text_array WHERE v = toFixedString('ab', 2) SETTINGS force_data_skipping_indices = 'idx'; -- { serverError INDEX_NOT_USED }

SELECT '-- Array and Map columns';
DROP TABLE IF EXISTS tab_array_string;
DROP TABLE IF EXISTS tab_array_fixed_string;
DROP TABLE IF EXISTS tab_map;
CREATE TABLE tab_array_string (k UInt32, a Array(String), INDEX idx a TYPE bloom_filter GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_array_string SELECT number, [['ab', 'ab\0', 'ab\0\0', 'zz'][number + 1]] FROM numbers(4);
CREATE TABLE tab_array_fixed_string (k UInt32, a Array(FixedString(4)), INDEX idx a TYPE bloom_filter GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_array_fixed_string SELECT number, [['ab', 'zz'][number + 1]] FROM numbers(2);
CREATE TABLE tab_map (k UInt32, m Map(FixedString(4), FixedString(4)), INDEX idx_keys mapKeys(m) TYPE bloom_filter GRANULARITY 1, INDEX idx_values mapValues(m) TYPE bloom_filter GRANULARITY 1) ENGINE = MergeTree ORDER BY k SETTINGS index_granularity = 1;
INSERT INTO tab_map SELECT number, map(['ab', 'zz'][number + 1], ['cd', 'yy'][number + 1]) FROM numbers(2);
SELECT 'tab_array_string', 'has(a, toFixedString(\'ab\', 2))', count() AS c, c = (SELECT count() FROM tab_array_string WHERE has(a, toFixedString('ab', 2)) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE has(a, toFixedString('ab', 2));
SELECT 'tab_array_string', 'hasAny(a, [toFixedString(\'ab\', 2)])', count() AS c, c = (SELECT count() FROM tab_array_string WHERE hasAny(a, [toFixedString('ab', 2)]) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE hasAny(a, [toFixedString('ab', 2)]);
SELECT 'tab_array_string', 'hasAll(a, [toFixedString(\'ab\', 2)])', count() AS c, c = (SELECT count() FROM tab_array_string WHERE hasAll(a, [toFixedString('ab', 2)]) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE hasAll(a, [toFixedString('ab', 2)]);
SELECT 'tab_array_string', 'indexOf(a, toFixedString(\'ab\', 2)) != 0', count() AS c, c = (SELECT count() FROM tab_array_string WHERE indexOf(a, toFixedString('ab', 2)) != 0 SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE indexOf(a, toFixedString('ab', 2)) != 0;
SELECT 'tab_array_string', 'arrayJoin(a) = toFixedString(\'ab\', 2)', count() AS c, c = (SELECT count() FROM tab_array_string WHERE arrayJoin(a) = toFixedString('ab', 2) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE arrayJoin(a) = toFixedString('ab', 2);
SELECT 'tab_array_string', 'has(a, toFixedString(\'ab\', 6))', count() AS c, c = (SELECT count() FROM tab_array_string WHERE has(a, toFixedString('ab', 6)) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE has(a, toFixedString('ab', 6));
SELECT 'tab_array_string', 'hasAny(a, [toFixedString(\'ab\', 6)])', count() AS c, c = (SELECT count() FROM tab_array_string WHERE hasAny(a, [toFixedString('ab', 6)]) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE hasAny(a, [toFixedString('ab', 6)]);
SELECT 'tab_array_string', 'hasAll(a, [toFixedString(\'ab\', 6)])', count() AS c, c = (SELECT count() FROM tab_array_string WHERE hasAll(a, [toFixedString('ab', 6)]) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE hasAll(a, [toFixedString('ab', 6)]);
SELECT 'tab_array_string', 'indexOf(a, toFixedString(\'ab\', 6)) != 0', count() AS c, c = (SELECT count() FROM tab_array_string WHERE indexOf(a, toFixedString('ab', 6)) != 0 SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE indexOf(a, toFixedString('ab', 6)) != 0;
SELECT 'tab_array_string', 'arrayJoin(a) = toFixedString(\'ab\', 6)', count() AS c, c = (SELECT count() FROM tab_array_string WHERE arrayJoin(a) = toFixedString('ab', 6) SETTINGS use_skip_indexes = 0) FROM tab_array_string WHERE arrayJoin(a) = toFixedString('ab', 6);
